class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final row and column to position
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Group picks by player
        player_picks = {}
        for player, color in pick:
            if player not in player_picks:
                player_picks[player] = {}
            player_picks[player][color] = player_picks[player].get(color, 0) + 1

        winning_count = 0

        # Check each player
        for player in range(n):
            if player not in player_picks:
                continue

            # Find maximum count of any color for this player
            max_count = max(player_picks[player].values())

            # Player wins if they have at least (player + 1) balls of same color
            if max_count >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed to make all rows palindromic
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate flips needed to make all columns palindromic
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return minimum of row flips and column flips
        return min(row_flips, col_flips)

